class Solution {
    public List<List<String>> mostPopularCreator(String[] creators, String[] ids, int[] views) {
        // Create a map to store the total views for each creator
        Map<String, Integer> creatorViews = new HashMap<>();
        // Create a map to store the most popular video for each creator
        Map<String, String> mostPopularVideo = new HashMap<>();

        // Iterate over the input arrays
        for (int i = 0; i < creators.length; i++) {
            String creator = creators[i];
            String id = ids[i];
            int view = views[i];

            // Update the total views for the creator
            creatorViews.put(creator, creatorViews.getOrDefault(creator, 0) + view);

            // Check if this is the most popular video for the creator
            if (!mostPopularVideo.containsKey(creator) || view > views[mostPopularVideo.get(creator)]) {
                mostPopularVideo.put(creator, id);
            }
        }

        // Find the maximum total views
        int maxViews = 0;
        for (int viewsCount : creatorViews.values()) {
            maxViews = Math.max(maxViews, viewsCount);
        }

        // Collect the most popular videos for each creator with the maximum total views
        List<List<String>> result = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : creatorViews.entrySet()) {
            if (entry.getValue() == maxViews) {
                String creator = entry.getKey();
                String mostPopularId = mostPopularVideo.get(creator);
                result.add(Arrays.asList(creator, mostPopularId));
            }
        }

        return result;
    }
