                    count[node] += count[child]
                    res[node] += res[child] + count[child]

        def dfs2(node, parent):
            for child in tree[node]:
                if child != parent:
                    res[child] = res[node] - count[child] + len(tree) - count[child]
                    dfs2(child, node)

        dfs(target.val, -1)
        dfs2(target.val, -1)

        return [i for i, j in enumerate(res) if j == K]

