#include <vector>
#include <queue>

int shortestDistance(vector<vector<int>>& maze, vector<int>& start, vector<int>& destination) {
    int rows = maze.size();
    int cols = maze[0].size();
    vector<vector<int>> dist(rows, vector<int>(cols, INT_MAX));
    dist[start[0]][start[1]] = 0;
    queue<pair<int, int>> q;
    q.push({start[0], start[1]});

    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();

        for (auto& dir : {{-1, 0}, {1, 0}, {0, -1}, {0, 1}}) {
            int nx = x;
            int ny = y;
            int d = 0;
            while (nx + dir[0] >= 0 && nx + dir[0] < rows && ny + dir[1] >= 0 && ny + dir[1] < cols && maze[nx + dir[0]][ny + dir[1]] == 0) {
                nx += dir[0];
                ny += dir[1];
                d++;
            }

            if (dist[x][y] + d < dist[nx - dir[0]][ny - dir[1]]) {
                dist[nx - dir[0]][ny - dir[1]] = dist[x][y] + d;
                q.push({nx - dir[0], ny - dir[1]});
            }
        }
    }

    return dist[destination[0]][destination[1]] == INT_MAX ? -1 : dist[destination[0]][destination[1]];
}

