            }
        }

        // Create a priority queue to store the nodes to be visited
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[2] - b[2]);
        pq.add(new int[]{positions.get(pos1[0] + "," + pos1[1]), positions.get(pos2[0] + "," + pos2[1]), 0});

        // Create a boolean array to keep track of visited nodes
        boolean[] visited = new boolean[graph.length * graph[0].length];

        while (!pq.isEmpty()) {
            int[] current = pq.poll();
            int x = current[0] / graph[0].length;
            int y = current[0] % graph[0].length;

            // If the current node is the destination node, return the distance
            if (x == current[1] / graph[0].length && y == current[1] % graph[0].length) {
                return current[2];
