#include <iostream>
#include <vector>
#include <algorithm>

std::vector<std::vector<int>> floodFill(std::vector<std::vector<int>>& image, int sr, int sc, int newColor) {
    int rows = image.size();
    if (rows == 0) return image;
    int cols = image[0].size();
    if (cols == 0) return image;

    int originalColor = image[sr][sc];
    if (originalColor == newColor) return image;

    std::queue<std::pair<int, int>> q;
    q.push({sr, sc});
    image[sr][sc] = newColor;

    while (!q.empty()) {
        int r = q.front().first;
        int c = q.front().second;
        q.pop();

        // Check up
        if (r > 0 && image[r-1][c] == originalColor) {
            q.push({r-1, c});
            image[r-1][c] = newColor;
        }

        // Check down
        if (r < rows-1 && image[r+1][c] == originalColor) {
            q.push({r+1, c});
            image[r+1][c] = newColor;
        }

        // Check left
        if (c > 0 && image[r][c-1] == originalColor) {
            q.push({r, c-1});
            image[r][c-1] = newColor;
        }

        // Check right
        if (c < cols-1 && image[r][c+1] == originalColor) {
            q.push({r, c+1});
            image[r][c+1] = newColor;
        }
    }

    return image;
}

