    int sr = 1, sc = 1, newColor = 2;
    image = floodFill(image, sr, sc, newColor);

    for (const auto& row : image) {
        for (int val : row) {
            std::cout << val << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}

