                if (i == j) continue;
                String concat = words[i] + words[j];

                boolean isPalindrome = true;
                for (int left = 0, right = concat.length() - 1; left < right; left++, right--) {
                    if (concat.charAt(left) != concat.charAt(right)) {
                        isPalindrome = false;
                        break;
                    }
                }

