import java.util.*;

class Solution {
    public boolean canFinish(int numCourses, int[][] prerequisites) {
        // Create an adjacency list representation of the graph
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < numCourses; i++) {
            graph.add(new ArrayList<>());
        }
        for (int[] prerequisite : prerequisites) {
            graph.get(prerequisite[0]).add(prerequisite[1]);
        }

        // Perform topological sorting on the graph
        Stack<Integer> stack = new Stack<>();
        boolean[] visited = new boolean[numCourses];
        for (int i = 0; i < numCourses; i++) {
            if (!visited[i]) {
                dfs(graph, visited, i, stack);
            }
        }

        // Check if there are any cycles in the graph
        while (!stack.isEmpty()) {
            int course = stack.pop();
            visited = new boolean[numCourses];
            if (!dfsCycle(graph, visited, course)) {
                return false;
            }
        }

        return true;
    }

    private void dfs(List<List<Integer>> graph, boolean[] visited, int course, Stack<Integer> stack) {
        visited[course] = true;
        for (int neighbor : graph.get(course)) {
            if (!visited[neighbor]) {
                dfs(graph, visited, neighbor, stack);
            }
        }
        stack.push(course);
    }

    private boolean dfsCycle(List<List<Integer>> graph, boolean[] visited, int course) {
        visited[course] = true;
        for (int neighbor : graph.get(course)) {
            if (!visited[neighbor]) {
                if (dfsCycle(graph, visited, neighbor)) {
                    return true;
                }
            } else {
                return true;
            }
        }
        return false;
    }
}

