int minSwaps(std::vector<int>& nums, int k) {
    int n = nums.size();
    std::vector<int> window(k, 0);

    // Count the number of zeros in the first window
    for (int i = 0; i < k; ++i) {
        if (nums[i] == 0) {
            window[i]++;
        }
    }

    int min_swaps = k;
    for (int i = k; i < n; ++i) {
        // Add the new element to the window
        if (nums[i] == 0) {
            window[i % k]++;
        }

        // Remove the old element from the window
        if (nums[i - k] == 0) {
            window[(i - k) % k]--;
        }

        // Update the minimum swaps needed
        min_swaps = std::min(min_swaps, k - std::count(window.begin(), window.end(), 0));
    }
    return min_swaps;
}

