import java.util.Arrays;

public class Solution {
    public int maxProfitAssignment(int[] difficulty, int[] profit, int[] worker) {
        int[][] jobs = new int[difficulty.length][2];
        for (int i = 0; i < difficulty.length; i++) {
            jobs[i][0] = difficulty[i];
            jobs[i][1] = profit[i];
        }
        Arrays.sort(jobs, (a, b) -> a[0] - b[0]);
        int maxProfit = 0;
        for (int i = 0; i < worker.length; i++) {
            int currentWorker = worker[i];
            int jobIndex = binarySearch(jobs, currentWorker);
            if (jobIndex >= 0) {
                maxProfit += jobs[jobIndex][1];
            }
        }
        return maxProfit;
    }

    private int binarySearch(int[][] jobs, int target) {
        int left = 0;
        int right = jobs.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (jobs[mid][0] <= target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return right;
    }

    public static void main(String[] args) {
        Solution solution = new Solution();
        int[] difficulty = {1, 3, 5, 2};
        int[] profit = {2, 3, 1, 14};
        int[] worker = {1, 4, 6};
        System.out.println(solution.maxProfitAssignment(difficulty, profit, worker)); // Output: 8
    }
}

