import java.util.*;

class Solution {
    public int advantageCount(int[] nums1, int[] nums2, int k) {
        int n = nums1.length;
        int[] result = new int[n];
        TreeMap<Integer, PriorityQueue<Integer>> map = new TreeMap<>();
        for (int i = 0; i < n; i++) {
            map.computeIfAbsent(nums2[i], key -> new PriorityQueue<>()).offer(nums1[i]);
        }
        for (int i = 0; i < n; i++) {
            Map.Entry<Integer, PriorityQueue<Integer>> entry = map.lastEntry();
            if (entry.getValue().size() == 1) {
                entry.getValue().poll();
                continue;
            }
            int num = entry.getValue().poll();
            if (entry.getValue().isEmpty()) {
                map.pollLastEntry();
            }
            result[i] = num;
        }
        return Arrays.stream(result).sum();
    }
}

