    public static int minCoins(int[] coins, int amount) {
        Arrays.sort(coins);

        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        int count = 0;

        for (int coin : coins) {
            while (amount >= coin) {
                amount -= coin;
                pq.offer(coin);
                count++;
            }
        }

        return count;
    }

