    public static int countPairsWithSumInRange(int[] nums, int k) {
        Arrays.sort(nums);
        int left = 0;
        int right = nums.length - 1;
        int count = 0;
        while (left < right) {
            if (nums[left] + nums[right] <= k) {
                count += right - left;
                left++;
            } else {
                right--;
            }
        }
        return count;
    }

