class Solution {
    public int minKBitFlips(int[] A, int K) {
        int n = A.length;
        int[] flip = new int[n];
        int res = 0;

        for (int i = 0; i < n; ++i) {
            if (i >= K) flip[i - K] = 0;
            if (i > 0) flip[i] ^= flip[i - 1];
            if ((A[i] ^ flip[i]) == 0) {
