bool isSumPossible(const std::vector<int>& arr, int target) {
    int n = arr.size();
    std::sort(arr.begin(), arr.end());
    for (int i = 0; i < n; ++i) {
        int left = i + 1, right = n - 1;
        while (left < right) {
            int sum = arr[i] + arr[left] + arr[right];
