public class Solution {
    public int largestSumSequence(int[] nums, int k) {
        PriorityQueue<Integer> minHeap = new PriorityQueue<>(k);

        for (int num : nums) {
            minHeap.offer(num);
            if (minHeap.size() > k) {
                minHeap.poll();
            }
        }

        int[] result = new int[k];
        for (int i = k - 1; i >= 0; i--) {
            result[i] = minHeap.poll();
        }

        return result;
    }

    // New function to find the maximum sum of any sequence of k consecutive nodes in a tree
    public int maxSumOfKConsecutiveNodes(int n, int[][] edges) {
        // Build the adjacency list representation of the tree
        List<List<Integer>> adjList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adjList.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            adjList.get(edge[0]).add(edge[1]);
            adjList.get(edge[1]).add(edge[0]);
        }

        // Initialize the result variable
        int result = Integer.MIN_VALUE;

        // Iterate over all possible starting nodes
        for (int i = 0; i < n; i++) {
            // Use a priority queue to keep track of the k largest sums encountered so far
            PriorityQueue<Integer> pq = new PriorityQueue<>();
            // Iterate over all possible sequences of k consecutive nodes starting from node i
            for (int j = i; j < n && adjList.get(i).size() > 0; j++) {
                // Add the current node to the sequence
                pq.offer(j);
                // If the sequence has k nodes, calculate its sum and update the result
