                    int sum = 0;
                    for (int x : pq) {
                        sum += x;
                    }
                    result = Math.max(result, sum);
                    // Remove the first node from the sequence
                    pq.poll();
                }
                // Add the next node in the sequence
                for (int neighbor : adjList.get(j)) {
                    if (!pq.contains(neighbor)) {
                        pq.offer(neighbor);
                    }
                }
            }
        }

        return result;
    }
}

