import java.util.*;

class Solution {
    public int shortestPathAllKeys(String[] grid) {
        int m = grid.length, n = grid[0].length;
        Queue<int[]> queue = new LinkedList<>();
        Set<String> visited = new HashSet<>();
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        // Find the starting position and collect all keys
        int startX = -1, startY = -1;
        int keyCount = 0;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                char c = grid[i].charAt(j);
                if (c == '@') {
                    startX = i;
                    startY = j;
                } else if (Character.isLowerCase(c)) {
                    keyCount++;
                }
            }
        }

        // Initialize the queue with the starting position
        queue.offer(new int[]{startX, startY, 0});
        visited.add(startX + "," + startY + "," + 0);

        int steps = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int k = 0; k < size; ++k) {
                int[] pos = queue.poll();
                int x = pos[0], y = pos[1], keys = pos[2];

                // Check if all keys have been collected
                if (keys == (1 << keyCount) - 1) return steps;

                // Explore neighbors
                for (int[] dir : directions) {
                    int nx = x + dir[0], ny = y + dir[1];
                    if (nx >= 0 && nx < m && ny >= 0 && ny < n) {
                        char c = grid[nx].charAt(ny);
                        if (Character.isLowerCase(c)) {
                            int newKey = keys | (1 << (c - 'a'));
                            String state = nx + "," + ny + "," + newKey;
                            if (!visited.contains(state)) {
                                queue.offer(new int[]{nx, ny, newKey});
                                visited.add(state);
                            }
                        } else if (Character.isUpperCase(c)) {
                            int lowerCase = Character.toLowerCase(c) - 'a';
                            if (((keys >> lowerCase) & 1) == 1) {
                                String state = nx + "," + ny + "," + keys;
                                if (!visited.contains(state)) {
                                    queue.offer(new int[]{nx, ny, keys});
                                    visited.add(state);
                                }
                            }
                        } else if (c == '.') {
                            String state = nx + "," + ny + "," + keys;
                            if (!visited.contains(state)) {
                                queue.offer(new int[]{nx, ny, keys});
                                visited.add(state);
                            }
                        }
                    }
                }
            }
            steps++;
        }
        return -1;
    }
}

