    std::vector<int> dp(n, 0);
    dp[0] = nums[0];
    for (int i = 1; i < n; i++) {
        dp[i] = std::max(dp[i-1], nums[i]);
        for (int j = i-1; j >= 0; j--) {
            if (i-j+1 >= 2) {
                dp[i] = std::max(dp[i], dp[j-1] + nums[i]);
            }
        }
    }
    return *std::max_element(dp.begin(), dp.end());
}

