    public boolean wordPatternMatch(String pattern, String str) {
        Map<Character, String> map = new HashMap<>();
        Set<String> set = new HashSet<>();
        return match(pattern, str, 0, 0, map, set);
    }

    private boolean match(String pattern, String str, int p, int s, Map<Character, String> map, Set<String> set) {
        if (p == pattern.length() && s == str.length()) {
            return true;
        }
        if (p == pattern.length() || s == str.length()) {
            return false;
        }
        char c = pattern.charAt(p);
        if (map.containsKey(c)) {
            String value = map.get(c);
            if (!str.startsWith(value, s)) {
                return false;
            }
            return match(pattern, str, p + 1, s + value.length(), map, set);
        } else {
            for (int i = s; i < str.length(); i++) {
                String value = str.substring(s, i + 1);
                if (set.contains(value)) {
                    continue;
                }
                map.put(c, value);
                set.add(value);
                if (match(pattern, str, p + 1, i + 1, map, set)) {
                    return true;
                }
                map.remove(c);
                set.remove(value);
            }
        }
        return false;
    }
