int minCostToSupplyWater(int n, std::vector<int>& wells, std::vector<std::vector<int>>& pipes) {
    // Create a graph where each node represents a well or a pipe connection
    std::vector<std::vector<std::pair<int, int>>> graph(n + 1);
    for (int i = 0; i < n; i++) {
        graph[i + 1].emplace_back(0, wells[i]);
    }
    for (const auto& pipe : pipes) {
        graph[pipe[0]].emplace_back(pipe[1], pipe[2]);
        graph[pipe[1]].emplace_back(pipe[0], pipe[2]);
    }

    // Use Kruskal's algorithm to find the minimum spanning tree
    std::vector<std::pair<int, std::pair<int, int>>> edges;
    for (int i = 1; i <= n; i++) {
        for (const auto& neighbor : graph[i]) {
            edges.emplace_back(neighbor.second, {i, neighbor.first});
        }
    }
    std::sort(edges.begin(), edges.end());

    std::vector<int> parent(n + 1);
    for (int i = 1; i <= n; i++) {
        parent[i] = i;
    }

    int cost = 0;
    for (const auto& edge : edges) {
        int u = edge.second.first;
        int v = edge.second.second;
        if (find(parent, u) != find(parent, v)) {
            cost += edge.first;
            unionSets(parent, u, v);
        }
    }

