    public static boolean[] canMakePaliQueries(String s, int[][] queries) {
        int n = s.length();
        int[][] prefixSum = new int[n + 1][26];

        // Calculate the prefix sum array
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < 26; j++) {
                prefixSum[i][j] = prefixSum[i - 1][j];
            }
            prefixSum[i][s.charAt(i - 1) - 'a']++;
