class Solution {
    public int[] addToArrayForm(int[] A, int[] B) {
        int carry = 0;
        int i = A.length - 1, j = B.length - 1;
        int[] res = new int[Math.max(A.length, B.length) + 1];

        while (i >= 0 || j >= 0) {
            int sum = carry;
            if (i >= 0) sum += A[i--];
            if (j >= 0) sum += B[j--];
            res[--res.length] = sum % 10;
            carry = sum / 10;
        }

