public class Solution {
    public List<String> letterCombinations(String digits) {
        List<String> result = new ArrayList<>();
        if (digits == null || digits.isEmpty()) {
            return result;
        }
        findCombinations(digits, 0, new StringBuilder(), result);
        return result;
    }

    private void findCombinations(String digits, int index, StringBuilder current, List<String> result) {
        if (index == digits.length()) {
            result.add(current.toString());
            return;
        }

        String letters = getLetters(digits.charAt(index));
        for (char letter : letters.toCharArray()) {
            current.append(letter);
            findCombinations(digits, index + 1, current, result);
            current.deleteCharAt(current.length() - 1);
        }
    }

    private String getLetters(char digit) {
        switch (digit) {
            case '2':
                return "abc";
            case '3':
                return "def";
            case '4':
                return "ghi";
            case '5':
                return "jkl";
            case '6':
