import java.util.ArrayList;
import java.util.List;

public class Permutations {

    // Original function to generate all permutations of an array
    public static List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> results = new ArrayList<>();
        helper(nums, 0, results);
        return results;
    }

    // Helper function to recursively generate permutations
    private static void helper(int[] nums, int index, List<List<Integer>> results) {
        if (index == nums.length - 1) {
            List<Integer> tempList = new ArrayList<>();
            for (int n : nums) {
                tempList.add(n);
            }
            results.add(tempList);
            return;
        }

        for (int i = index; i < nums.length; i++) {
            swap(nums, index, i);
            helper(nums, index + 1, results);
            swap(nums, index, i); // Backtrack
        }
    }

    // Function to find the next permutation in lexicographical order
    public static List<Integer> nextPermutation(int[] nums) {
        int n = nums.length;
        int i = n - 2;
        while (i >= 0 && nums[i] >= nums[i + 1]) {
            i--;
        }

        if (i >= 0) {
            int j = n - 1;
            while (j > i && nums[j] <= nums[i]) {
                j--;
            }
            swap(nums, i, j);
        }

        reverse(nums, i + 1, n - 1);
        return Arrays.stream(nums).boxed().collect(Collectors.toList());
    }

    // Helper function to swap elements in an array
    private static void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }

    // Helper function to reverse a portion of an array
    private static void reverse(int[] nums, int start, int end) {
        while (start < end) {
            swap(nums, start, end);
            start++;
            end--;
        }
    }

    public static void main(String[] args) {
        int[] nums = {1, 2, 3};
        System.out.println(nextPermutation(nums)); // Output: [1, 3, 2]
    }
}

