class Solution:
    def longestConsecutive(self, root: TreeNode) -> int:
        if not root:
            return 0

        stack = [(root, 1)]
        longestSeq = 1

        while stack:
            node, seq = stack.pop()

            if node.left:
                if node.left.val == node.val + 1:
                    stack.append((node.left, seq + 1))
                else:
                    stack.append((node.left, 1))

                longestSeq = max(longestSeq, seq + 1)

            if node.right:
                if node.right.val == node.val + 1:
                    stack.append((node.right, seq + 1))
                else:
                    stack.append((node.right, 1))

                longestSeq = max(longestSeq, seq + 1)

        return longestSeq

