vector<vector<int>> findSCCs(int n, vector<vector<int>>& edges) {
    vector<int> inDegree(n, 0);
    vector<vector<int>> adjList(n);
    vector<vector<int>> revAdjList(n);

    // Build the adjacency list and reverse adjacency list
    for (auto& e : edges) {
        adjList[e[0]].push_back(e[1]);
        revAdjList[e[1]].push_back(e[0]);
        inDegree[e[1]]++;
    }

    queue<int> q;
    for (int i = 0; i < n; i++) {
        if (inDegree[i] == 0) {
            q.push(i);
