    }

    vector<int> order;

    while (!q.empty()) {
        int curr = q.front();
        q.pop();
        order.push_back(curr);
        for (auto next : revAdjList[curr]) {
            if (--inDegree[next] == 0) {
                q.push(next);
            }
        }
    }

    reverse(order.begin(), order.end());

    vector<vector<int>> sccs;
    vector<bool> visited(n, false);

    for (int i = 0; i < n; i++) {
        if (visited[order[i]]) continue;
        vector<int> scc;
        dfs(order[i], adjList, visited, scc);
        sccs.push_back(scc);
    }

    return sccs;
