import java.util.Arrays;

public class Solution {
    public int lengthOfLIS(int[] nums) {
        int[] dp = new int[nums.length];
        int max_length = 1;
        Arrays.fill(dp, 1);
        for (int i = 1; i < nums.length; i++) {
            for (int j = 0; j < i; j++) {
                if (nums[i] > nums[j]) {
                    dp[i] = Math.max(dp[i], dp[j] + 1);
                }
            }
            max_length = Math.max(max_length, dp[i]);
        }
        return max_length;
    }

    public int findNumberOfLIS(int[] nums) {
        int n = nums.length;
        if (n == 0) return 0;

        int[] lengths = new int[n]; // lengths[i] = longest ending in nums[i]
        int[] counts = new int[n]; // counts[i] = number of longest ending in nums[i]

        Arrays.fill(lengths, 1);
        Arrays.fill(counts, 1);

        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (nums[i] > nums[j]) {
                    if (lengths[i] < lengths[j] + 1) {
                        lengths[i] = lengths[j] + 1;
                        counts[i] = counts[j];
                    } else if (lengths[i] == lengths[j] + 1) {
                        counts[i] += counts[j];
                    }
                }
            }
        }

        int max_length = 0;
        for (int len : lengths) {
            max_length = Math.max(max_length, len);
        }

        int result = 0;
        for (int i = 0; i < n; i++) {
            if (lengths[i] == max_length) {
                result += counts[i];
            }
        }

        return result;
    }

    public static void main(String[] args) {
        Solution solution = new Solution();
        int[] nums = {10, 9, 2, 5, 3, 7, 101, 18};
        System.out.println(solution.lengthOfLIS(nums)); // Output: 4

        int[][] envelopes = {{5, 4}, {6, 4}, {6, 7}, {2, 3}};
        System.out.println(solution.findNumberOfLIS(envelopes)); // Output: 3
    }
}

