import java.util.List;
import java.util.Map;

public class WordSquares {

    public static boolean isWordSquare(String[] words) {
        // Check if the input array is null or empty
        if (words == null || words.length == 0) {
            return false;
        }

        // Get the length of the first word
        int length = words[0].length();

        // Create a map to store the prefixes of each word
        Map<String, List<String>> prefixMap = new HashMap<>();

        // Populate the prefix map
        for (String word : words) {
            for (int i = 1; i <= word.length(); i++) {
                String prefix = word.substring(0, i);
                if (!prefixMap.containsKey(prefix)) {
                    prefixMap.put(prefix, new ArrayList<>());
                }
                prefixMap.get(prefix).add(word);
            }
        }

        // Check if all words have the same length
        for (String word : words) {
            if (word.length() != length) {
                return false;
            }
        }

        // Check if the first character of each word matches the corresponding prefix
        for (int i = 0; i < length; i++) {
            String prefix = "";
            for (String word : words) {
                prefix += word.charAt(i);
            }
            if (!prefixMap.containsKey(prefix)) {
                return false;
            }
        }

        return true;
    }

    public static void main(String[] args) {
        String[] words = {"abcd", "bnrt", "crmy", "dtye"};
        System.out.println(isWordSquare(words)); // Output: true
    }
}

