import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<List<String>> wordSquares(String[] words) {
        List<List<String>> result = new ArrayList<>();
        if (words == null || words.length == 0) {
            return result;
        }

        List<String> current = new ArrayList<>();
        backtrack(words, 0, current, result);

        return result;
    }

    private void backtrack(String[] words, int length, List<String> current, List<List<String>> result) {
        if (current.size() == length) {
            result.add(new ArrayList<>(current));
            return;
        }

        String prefix = "";
        for (String word : current) {
            prefix += word.charAt(current.size());
        }

        for (String word : getWordsWithPrefix(words, prefix)) {
            current.add(word);
            backtrack(words, length, current, result);
            current.remove(current.size() - 1);
        }
    }

    private List<String> getWordsWithPrefix(String[] words, String prefix) {
        List<String> result = new ArrayList<>();
        for (String word : words) {
            if (word.startsWith(prefix)) {
                result.add(word);
            }
        }
        return result;
    }

