def dfs(nums, start, path, res):
    if len(path) >= 2:
        res.add(tuple(path))
    for i in range(start, len(nums)):
        if path and path[-1] > nums[i]:
            continue
        dfs(nums, i + 1, path + [nums[i]], res)

def countDistinctSubsequences(pairs: List[List[int]]) -> int:
    nums = sorted(set([num for pair in pairs for num in pair]))
    res = set()
    dfs(nums, 0, [], res)
    return len(res)

