            int row = (i / 2) / 3;
            int col = (i / 2) % 3;

            if (player == 'X') {
                rows[row]++;
                cols[col]++;
                if (row == col) diag++;
                if (row + col == 2) antiDiag++;
            } else if (player == 'O') {
                rows[row]--;
                cols[col]--;
                if (row == col) diag--;
                if (row + col == 2) antiDiag--;
            }
